using System;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace GearLab {
 public sealed partial class TrainDesignerForm {
  CheckBox commonHousing;PropertyGrid housingProperties;CompoundSectionPanel compoundSection;
  void InitializeCompound(EditorTabs tabs){var page=new TabPage("Общий корпус");var split=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=300,FixedPanel=FixedPanel.Panel1,Size=new Size(900,650)};page.Controls.Add(split);commonHousing=new CheckBox{Text="Общий корпус",Dock=DockStyle.Top,Height=38,AccessibleName="Общий корпус"};housingProperties=new PropertyGrid{Dock=DockStyle.Fill,ToolbarVisible=false,HelpVisible=true,PropertySort=PropertySort.NoSort};split.Panel1.Controls.Add(housingProperties);split.Panel1.Controls.Add(commonHousing);commonHousing.CheckedChanged+=(a,b)=>{if(loading)return;if(document.SharedHousing==null)document.SharedHousing=new SharedHousingSettings();document.SharedHousing.Enabled=commonHousing.Checked;housingProperties.SelectedObject=document.SharedHousing;Changed();};housingProperties.PropertyValueChanged+=(a,b)=>{if(!loading){RefreshCompound();Changed();}};compoundSection=new CompoundSectionPanel{Dock=DockStyle.Fill};split.Panel2.Controls.Add(compoundSection);tabs.TabPages.Add(page);RefreshCompound();}
  void RefreshCompound(){if(commonHousing==null)return;bool was=loading;loading=true;commonHousing.Checked=CompoundReducer.Enabled(document);housingProperties.SelectedObject=document.SharedHousing??new SharedHousingSettings();housingProperties.Enabled=commonHousing.Checked;loading=was;}
  void ShowCompound(TrainSolution s){if(compoundSection==null)return;compoundSection.Solution=s;compoundSection.Invalidate();if(s.Compound!=null){summary.Text+="\n"+(document.SharedHousing.Shape=="Square"?"□ ":"Ø ")+Engine.F(s.Compound.Diameter)+" × "+Engine.F(s.Compound.Height)+" мм · "+Engine.F(s.Mass)+" кг · КПД "+Engine.F(s.TotalEfficiency);status.Text="Предварительная конструкция. Прочность, ресурс подшипников и нагрев не рассчитаны. ReadyForManufacture=false.";}}
 }
 public sealed class CompoundSectionPanel:Panel {
  public TrainSolution Solution;public CompoundSectionPanel(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(UiPalette.Get("Field"));var s=Solution;if(s==null||s.Compound==null){TextRenderer.DrawText(g,I18n.T("Включите общий корпус и дождитесь расчёта."),Font,ClientRectangle,UiPalette.Get("Muted"),TextFormatFlags.WordBreak);return;}var l=s.Compound;float scale=(float)Math.Min((Width-80)/l.Diameter,(Height-120)/l.Height),cx=Width/2f,bottom=Height-45;Func<double,float> yy=z=>bottom-(float)z*scale;float r=(float)l.Diameter*scale/2;using(var pen=new Pen(UiPalette.Get("Accent"),2))using(var brush=new SolidBrush(Color.FromArgb(70,UiPalette.Get("Accent")))){g.FillRectangle(brush,cx-r,yy(l.MotorPlate),2*r,(float)l.MotorPlate*scale);foreach(var m in l.Modules){float top=yy(m.Top),b=yy(m.Bottom);g.DrawRectangle(pen,cx-r,top,2*r,b-top);float wall=Math.Max(4,6*scale);g.FillRectangle(brush,cx-r,top,wall,b-top);g.FillRectangle(brush,cx+r-wall,top,wall,b-top);g.FillRectangle(brush,cx-r,yy(m.PartitionTop),2*r,(float)(m.PartitionTop-m.Top)*scale);TextRenderer.DrawText(g,I18n.T(m.Name),Font,new Rectangle((int)(cx-r+12),(int)(top+3),(int)(2*r-24),32),UiPalette.Get("Text"),TextFormatFlags.EndEllipsis);}
    g.FillRectangle(brush,cx-r,yy(l.Height),2*r,(float)(l.Height-l.Modules.Last().PartitionTop)*scale);g.DrawLine(pen,cx,yy(0),cx,yy(l.OutputPlane));foreach(double z in new[]{l.Support1,l.Support2})g.DrawRectangle(pen,cx-10,yy(z)-4,20,8);}
   TextRenderer.DrawText(g,"i = "+Engine.F(s.TotalRatio)+" · Ø "+Engine.F(l.Diameter)+" × "+Engine.F(l.Height)+" мм",Font,new Rectangle(12,8,Width-24,32),UiPalette.Get("Text"));TextRenderer.DrawText(g,I18n.T("Схематический разрез · конструкция предварительная"),Font,new Rectangle(12,Height-32,Width-24,30),UiPalette.Get("Muted"));}
 }
}
